const cfg = $('⚙️ Configuration').first().json;
const prev = $('Scrape + confiance email/LinkedIn').first().json;
const q = ($input.item.json.output || $input.item.json);
const s = $getWorkflowStaticData('global');

const decision = String(q.decision || 'INCERTAIN').toUpperCase();
const score = Number(q.score_ia) || 0;
const score_ok = score >= (cfg.score_min || 55);
const duplicate = !!(s.notion_sirens && s.notion_sirens[prev.siren]);

const prenom = (prev.dirPrenom || '').trim();
const agence = (prev.nom || '').trim();
const angle = q.angle || 'reporting client automatisé';

const message_email_m1 = prenom
  ? `Objet: Question rapide — reporting chez ${agence}\n\nBonjour ${prenom},\n\nJe vois que ${agence} gère un portefeuille clients — sur ce type d'agence, le reporting récurrent mange souvent des heures chaque semaine.\n\nJ'ai une démo Loom de 2 min sur comment automatiser ça (sans changer vos outils). Si ça t'intéresse, réponds DEMO.\n\nSedera`
  : `Objet: Question rapide — reporting agence\n\nBonjour,\n\nJe travaille avec des agences francophones sur l'automatisation du reporting client. Démo 2 min dispo — réponds DEMO si curieux.\n\nSedera`;

const note_linkedin = prenom
  ? `Salut ${prenom}, je vois ${agence} — je bosse sur l'automatisation du reporting client pour les agences. Content de me connecter.`
  : `Bonjour, je vois ${agence} — je bosse sur l'automatisation ops agence. Content de me connecter.`;

const notes = [
  `canal: email+linkedin`,
  `email_confiance: ${prev.email_confiance}`,
  prev.email_source_page ? `email_source: ${prev.email_source_page}` : '',
  prev.email_scrape ? `email_scrape: ${prev.email_scrape}` : '',
  prev.email_hypotheses ? `email_hypotheses: ${prev.email_hypotheses}` : '',
  `mx_ok: ${prev.mx_ok}`,
  `linkedin_confiance: ${prev.linkedin_confiance}`,
  prev.linkedin_search && !prev.linkedin_url ? `linkedin_search: ${prev.linkedin_search}` : '',
  `score: ${score}`,
  `angle: ${angle}`,
  prev.emails_detectes ? `emails_detectes: ${prev.emails_detectes}` : '',
  `message_email_m1: ${message_email_m1.replace(/\n/g, ' \\n ')}`,
  `note_linkedin: ${note_linkedin}`,
  prev.email_confiance === 'generique_site' ? '⚠️ email_generique — vérifier destinataire avant envoi' : '',
  prev.email_hypotheses && !prev.email_pour_notion ? '⚠️ pas d email scrapé — NE PAS utiliser les hypothèses sans vérif manuelle' : '',
].filter(Boolean).join(' | ');

const ok_pour_notion = prev.hasContactChannel && !duplicate && decision !== 'NON' && score_ok
  && (prev.email_pour_notion || prev.linkedin_url || prev.linkedin_search);

return [{
  json: {
    ...prev,
    decision, score_ia: score,
    liste: q.liste || (score >= 75 ? 'A-list' : (score >= 55 ? 'B-list' : 'C-list')),
    angle, raison_ia: q.raison || '',
    message_email_m1, note_linkedin, notes_notion: notes,
    ok_pour_notion,
  },
}];

const s = $getWorkflowStaticData('global');
const lead = $('Finaliser fiche dual-channel').first()?.json || $('Scrape + confiance email/LinkedIn').first()?.json;
if (lead?.siren) s.notion_sirens[lead.siren] = true;
return [{ json: { siren: lead?.siren, ok: true } }];
